#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maxAlternatingSumOfSquares(vector<int>& nums) {
        vector<int> sorted_nums = nums;
        sort(sorted_nums.rbegin(), sorted_nums.rend());
        int n = sorted_nums.size();
        int pos_count = (n + 1) / 2;
        long long ans = 0;
        for (int i = 0; i < pos_count; ++i) {
            ans += 1LL * sorted_nums[i] * sorted_nums[i];
        }
        for (int i = pos_count; i < n; ++i) {
            ans -= 1LL * sorted_nums[i] * sorted_nums[i];
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long maxAlternatingSumOfSquares(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int n = sorted.length;
        int posCount = (n + 1) / 2;
        long ans = 0;
        for (int i = n - 1; i >= n - posCount; i--) {
            ans += (long)sorted[i] * sorted[i];
        }
        for (int i = n - posCount - 1; i >= 0; i--) {
            ans -= (long)sorted[i] * sorted[i];
        }
        return ans;
    }
}

var maxAlternatingSumOfSquares = function(nums) {
    const sorted = [...nums].sort((a, b) => b - a);
    const n = sorted.length;
    const posCount = Math.floor((n + 1) / 2);
    let ans = 0n;
    for (let i = 0; i < posCount; i++) {
        ans += BigInt(sorted[i]) * BigInt(sorted[i]);
    }
    for (let i = posCount; i < n; i++) {
        ans -= BigInt(sorted[i]) * BigInt(sorted[i]);
    }
    return Number(ans);
};
